const moods=[{title:'Quero desacelerar',description:'Verde, caminhada e uma pausa na cidade.',ids:['botanico','luz','ibirapuera'],icon:'❋'},{title:'Quero me surpreender',description:'Arte, cor e encontros pelo caminho.',ids:['copan','masp','beco'],icon:'✳'},{title:'Quero provar São Paulo',description:'Sabores e arte para abrir o apetite.',ids:['mercado','feira','liberdade'],icon:'◒'}];
const mapQueries={"pizzapaulista":"Vila Mariana · São Paulo","pizzadoce":"Mooca · São Paulo","becocores":"Beco do Batman · Vila Madalena","kobra":"Mural de Eduardo Kobra · Avenida Paulista","parqueaugusta":"Parque Augusta São Paulo","burlemarx":"Parque Burle Marx · São Paulo","pinacoteca":"Pinacoteca · Luz","estacaoluz":"Estação da Luz · São Paulo",liberdade:'Praça da Liberdade São Paulo',feira:'Feiras livres São Paulo',beco:'Beco do Batman São Paulo',minhocao:'Minhocão São Paulo',ibirapuera:'Parque Ibirapuera São Paulo',cantareira:'Parque Estadual da Cantareira Núcleo Pedra Grande',mercado:'Mercado Municipal Paulistano São Paulo',paulista:'Avenida Paulista São Paulo',copan:'Edifício Copan São Paulo',masp:'MASP São Paulo',botanico:'Jardim Botânico São Paulo',luz:'Jardim da Luz São Paulo'};
let visited=new Set(safeIds(readLocal('sp-discoveries',[]),PLACE_IDS.length));
let route=safeIds(initialSharedTrip?.ids||readLocal('sp-trip',[]));route.forEach(id=>chosen.add(id));
const intro=document.createElement('section');intro.className='discovery';intro.id='descobrir';intro.innerHTML='<p class="eyebrow" id="mood-eyebrow"></p><h2 id="mood-heading"></h2><p id="mood-intro"></p><div id="moods" class="moods"></div><div class="passport"><div><h3 id="passport-title"></h3><p id="passport-help"></p></div><div><strong id="passport-progress"></strong><progress id="passport-meter" max="20" value="0"></progress><p id="passport-badge" aria-live="polite"></p><button id="clear-discoveries" class="text-button"></button></div></div>';
document.querySelector('#explorar').before(intro);
const itinerary=document.createElement('div');itinerary.className='itinerary';itinerary.innerHTML='<h3 id="trip-heading"></h3><p id="trip-help"></p><ol id="trip-items"></ol><button id="share-trip" class="secondary-button"></button><p id="trip-status" role="status"></p><input id="trip-link" readonly hidden aria-label="Link"><p id="trip-caveat" class="note"></p>';
document.querySelector('#selected').after(itinerary);
const lab=document.createElement('section');lab.className='lab';lab.id='laboratorio';lab.innerHTML='<div><p class="eyebrow" id="lab-eyebrow"></p><h2 id="lab-heading"></h2><p id="lab-intro"></p><label><span id="lab-select-label"></span><select id="lab-place"></select></label><p class="note" id="lab-note"></p></div><div><div class="comparison"><img id="lab-original" loading="lazy" decoding="async" width="720" height="960" alt=""><img id="lab-transformed" loading="lazy" decoding="async" width="720" height="960" class="comparison-after" alt=""><div class="compare-labels"><span id="label-original"></span><span id="label-transformed"></span></div></div><label for="lab-slider" id="lab-slider-label"></label><input id="lab-slider" type="range" min="0" max="100" value="50"></div>';
document.querySelector('.about').before(lab);
const shareImage=document.createElement('button');shareImage.id='share-image';shareImage.className='secondary-button';document.querySelector('#download').after(shareImage);const quotaNote=document.createElement('p');quotaNote.id='quota-note';quotaNote.className='note';document.querySelector('#status').after(quotaNote);
function synchronizeTrip(){route=[...chosen];writeLocal('sp-trip',route);document.dispatchEvent(new Event('tripchange'))}
function featureText(selector,key){document.querySelector(selector).textContent=t(key)}
function renderFeatures(){
 const current=[...chosen];if(JSON.stringify(route)!==JSON.stringify(current))synchronizeTrip();
 featureText('#mood-eyebrow','Monte seu olhar');featureText('#mood-heading','Três convites para começar');featureText('#mood-intro','Escolha um clima e descubra uma combinação de camadas. Você pode trocar os lugares depois.');
 $('#moods').replaceChildren(...moods.map((m,i)=>{const b=document.createElement('button');b.className='mood';b.dataset.mood=String(i);const icon=document.createElement('span');icon.className='mood-icon';icon.textContent=m.icon;const title=document.createElement('strong');title.textContent=t(m.title);const p=document.createElement('span');p.textContent=t(m.description);b.append(icon,title,p);return b}));
 featureText('#passport-title','Seu passaporte de descobertas');featureText('#passport-help','Abra as histórias para conhecer as camadas da cidade. Seu progresso fica neste navegador.');$('#passport-progress').textContent=`${visited.size}/${places.length} ${t('histórias exploradas')}`;$('#passport-meter').max=places.length;$('#passport-meter').value=visited.size;$('#passport-meter').setAttribute('aria-label',t('Seu passaporte de descobertas'));$('#passport-badge').textContent=visited.size===places.length?t('Você conheceu todas as camadas!'):visited.size>=3?t('Olhar de explorador desbloqueado ✳'):'';featureText('#clear-discoveries','Limpar minhas descobertas');
 featureText('#trip-heading','Minha sequência de descobertas');$('#trip-help').textContent=current.length?'':t('Escolha seus lugares acima para organizar a sequência do cartão.');featureText('#trip-caveat','Uma seleção afetiva, não um trajeto calculado. Confira distâncias e condições antes de sair.');
 $('#trip-items').replaceChildren(...current.map((id,index)=>{const p=places.find(x=>x.id===id),li=document.createElement('li'),name=document.createElement('strong'),a=document.createElement('a'),actions=document.createElement('div');name.textContent=t(p.title);a.textContent=t('Ver no mapa ↗');a.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(mapQueries[id]);a.target='_blank';a.rel='noopener noreferrer';actions.className='trip-actions';for(const delta of [-1,1]){const b=document.createElement('button');b.textContent=delta===-1?'↑':'↓';b.setAttribute('aria-label',`${t(delta===-1?'Mover para cima':'Mover para baixo')}: ${t(p.title)}`);b.dataset.move=id+':'+delta;b.disabled=index+delta<0||index+delta>=current.length;b.onclick=()=>{const next=[...chosen];[next[index],next[index+delta]]=[next[index+delta],next[index]];chosen.clear();next.forEach(x=>chosen.add(x));render()};actions.append(b)}li.append(name,a,actions);return li}));
 featureText('#share-trip','Copiar minha seleção');$('#share-trip').disabled=chosen.size!==3;featureText('#share-image','Compartilhar cartão');
 featureText('#lab-eyebrow','Antes e depois');featureText('#lab-heading','Da fotografia à sua lembrança');featureText('#lab-intro','Arraste para comparar o recorte e o tratamento de cor.');featureText('#lab-select-label','Escolher fotografia');featureText('#quota-note','20 fotografias preparadas com Cloudinary; cartão criado no seu dispositivo.');featureText('#label-original','Original');featureText('#label-transformed','Transformada');featureText('#lab-slider-label','Posição da comparação');
 const value=$('#lab-place').value||'liberdade';$('#lab-place').replaceChildren(...places.map(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=t(p.title);return o}));$('#lab-place').value=value;updateLab();
}
function updateLab(){const p=places.find(p=>p.id===$('#lab-place').value)||places[0];featureText('#lab-note',preparedMedia[p.id].engine==='local'?'Recorte e cor preparados localmente · arquivo entregue pelo próprio site':'Recorte para retrato · cor quente · qualidade automática');$('#lab-original').src=preparedMedia[p.id].original;$('#lab-transformed').src=preparedMedia[p.id].treated;$('#lab-original').alt=t('Original')+': '+t(p.title);$('#lab-transformed').alt=t('Transformada')+': '+t(p.title)}
$('#lab-place').onchange=updateLab;
$('#lab-slider').oninput=e=>{$('.comparison').className='comparison split-'+Math.round(Number(e.target.value))};
$('#moods').onclick=e=>{const button=e.target.closest('[data-mood]');if(!button)return;const mood=moods[Number(button.dataset.mood)];if(!mood)return;chosen.clear();mood.ids.forEach(id=>chosen.add(id));render();$('#status').textContent=t('Nova seleção pronta. Personalize seu cartão abaixo.')};
$('#cards').addEventListener('click',e=>{const id=e.target.closest('[data-story]')?.dataset.story;if(!PLACE_IDS.includes(id))return;visited.add(id);writeLocal('sp-discoveries',[...visited]);renderFeatures()});
$('#clear-discoveries').onclick=()=>{visited.clear();writeLocal('sp-discoveries',[]);renderFeatures();$('#passport-badge').textContent=t('Suas descobertas foram limpas deste navegador.')};
$('#share-trip').onclick=async()=>{if(chosen.size!==3)return;const url=new URL('/',location.origin);url.hash=new URLSearchParams({trip:[...chosen].join(','),lang:currentLanguage}).toString();try{await navigator.clipboard.writeText(url.href);$('#trip-status').textContent=t('Seleção copiada! O link leva apenas os lugares e o idioma, sem sua mensagem.')}catch{$('#trip-link').hidden=false;$('#trip-link').value=url.href;$('#trip-link').select();$('#trip-status').textContent=t('Copie o link abaixo para compartilhar sua seleção.')}};
addEventListener('hashchange',()=>{const shared=readSharedTrip(location.hash);if(!shared)return;chosen.clear();shared.ids.forEach(id=>chosen.add(id));if(currentLanguage!==shared.lang){$('#language').value=shared.lang;$('#language').dispatchEvent(new Event('change'))}else render()});
const originalRender=render;render=function(){originalRender();renderFeatures()};render();
